    for ch in s:
        if "a" <= ch <= "z":
            result.append(chr((ord(ch) - ord("a") + shift) % 26 + ord("a")))
        elif "A" <= ch <= "Z":
            result.append(chr((ord(ch) - ord("A") + shift) % 26 + ord("A")))
        else:
            result.append(ch)
    return "".join(result)

def is_anagram(first, second):
    a = "".join(ch.lower() for ch in first if ch.isalnum())
    b = "".join(ch.lower() for ch in second if ch.isalnum())
    return sorted(a) == sorted(b)

